        const commonTypes = ['Elf', 'Human', 'Wizard', 'Warrior', 'Dragon', 'Goblin', 'Zombie', 'Spirit', 'Soldier', 'Elemental', 'Ent', 'Hobbit'].filter((t: string) => !sagaCard._notedTypes.includes(t));
        const choices = [...new Set<string>([...handTypes, ...commonTypes])];

